mapper.select:
select count(record_id) from quality_stat_file_vw


		and platform  = #{platform} 


		and analysis_date  = #{analysis_date} 


		and subbarcode  = #{subbarcode} 


		and product_name  = #{product_name} 


		and data_type  = #{data_type}

select record_id,file_id,platform,product_name,subbarcode,data_type,file_type,stat_param_id,category,param_name,value,loaded_date,operator1,standard_value1,operator2,standard_value2
 from quality_stat_file_vw


		and platform  = #{platform} 


		and analysis_date  = #{analysis_date} 


		and subbarcode  = #{subbarcode} 


		and product_name  = #{product_name} 


		and data_type  = #{data_type} 


order by operator1 desc, operator2 desc, stat_param_id
limit #{pageNo},#{pageSize}
